struct nglFileBuf { void *Buf; unsigned int Size; };
struct HighScoreData { char initials[4]; char character[32]; int score; int icons; };
struct SurferData { char pad[508]; char fullname[32]; char tail[112]; };
struct GlobalDataClass { void setBeachHighScore(int, int, bool, HighScoreData) __asm__("setBeachHighScore__15GlobalDataClassiibG13HighScoreData"); };
class FEManager { public: void LoadScores() __asm__("LoadScores__9FEManager"); };
extern SurferData SurferDataArray[];
extern GlobalDataClass globalCareerData;
extern "C" void KSReadFile(const char *, nglFileBuf *, unsigned int) __asm__("KSReadFile__FPCcP10nglFileBufUi");
extern "C" void KSReleaseFile(nglFileBuf *) __asm__("KSReleaseFile__FP10nglFileBuf");
extern "C" int sscanf(const char *, const char *, ...);
extern "C" char *strcpy(char *, const char *);
extern "C" char *strchr(const char *, int);
__asm__(".equ SurferDataArray,0x004254E0");
__asm__(".equ globalCareerData,0x004349B8");
__asm__(".equ KSReadFile__FPCcP10nglFileBufUi,0x001E32A0");
__asm__(".equ KSReleaseFile__FP10nglFileBuf,0x001E3300");
__asm__(".equ setBeachHighScore__15GlobalDataClassiibG13HighScoreData,0x002F0118");
__asm__(".equ sscanf,0x003D3920");
__asm__(".equ strcpy,0x003D3FCC");
__asm__(".equ strchr,0x003D3CF8");
#define assert(x) ((void)0)
void FEManager::LoadScores()
{
    nglFileBuf F;
    KSReadFile("interface\\map\\default_high_scores.txt", &F, 1);
	if(!F.Buf)
	{
		KSReleaseFile(&F);
		assert(0);
	}
    char *s = (char *) F.Buf;

	HighScoreData tmp;
	unsigned int count = 0;
	while(s[count] == '/' || s[count] == '\r')
	{
		if(s[count] == '/' && count+1 < F.Size && s[count+1] == '*')
		{
			count += 2;
			while(count < F.Size && !(s[count] == '*' && count+1 < F.Size && s[count+1] == '/'))
				count++;
			count += 2;
		}
		if(s[count] == '\r') count += 2;
	}
	s = &s[count];

	for(int i=0; i<25*2; i++)
	{
		for(int j=0; j<10; j++)
		{
			count = 0;
			if(s[count] == '\r') count += 2;
			if(s[count] == '/' && count+1 < F.Size && s[count+1] == '*')
			{
				count += 2;
				while(count < F.Size && !(s[count] == '*' && count+1 < F.Size && s[count+1] == '/'))
					count++;
				count += 2;
			}

			if(s[count] == '\r') count++;
			if(s[count] == '\n') count++;

			int character;
			if(i < 25)
				sscanf(&s[count], "%s %d %d\n", tmp.initials, &character, &tmp.score);
			else sscanf(&s[count], "%s %d %d %d\n", tmp.initials, &character, &tmp.score, &tmp.icons);
			strcpy(tmp.character, SurferDataArray[character].fullname);

			int bn = i;
			if(bn >= 25) bn -= 25;
			globalCareerData.setBeachHighScore(bn, j, i >= 25, tmp);
			s = strchr(&s[count], '\n');
			if(s[0] == '\n') s = &s[1];
		}
	}

	KSReleaseFile(&F);
}
